import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.DIWxYxwh.js";const k=JSON.parse('{"title":"KV Cache 与 Prefix Caching 的调度流程","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/KV Cache 与 Prefix Caching 的调度流程.md","filePath":"LLM推理/KV Cache 与 Prefix Caching 的调度流程.md","lastUpdated":1791972048000}'),c={name:"LLM推理/KV Cache 与 Prefix Caching 的调度流程.md"};function h(n,t,i,r,d,s){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="kv-cache-与-prefix-caching-的调度流程" tabindex="-1">KV Cache 与 Prefix Caching 的调度流程 <a class="header-anchor" href="#kv-cache-与-prefix-caching-的调度流程" aria-label="Permalink to &quot;KV Cache 与 Prefix Caching 的调度流程&quot;">​</a></h1><h2 id="一、kv-cache-是什么" tabindex="-1">一、KV Cache 是什么 <a class="header-anchor" href="#一、kv-cache-是什么" aria-label="Permalink to &quot;一、KV Cache 是什么&quot;">​</a></h2><h3 id="_1-1-从注意力计算说起" tabindex="-1">1.1 从注意力计算说起 <a class="header-anchor" href="#_1-1-从注意力计算说起" aria-label="Permalink to &quot;1.1 从注意力计算说起&quot;">​</a></h3><p>Transformer 的注意力计算是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Attention(Q, K, V) = softmax(QKᵀ / √d) · V</span></span></code></pre></div><p>生成第 <code>t</code> 个 token 时，模型需要拿当前 token 的 Query，去和前面所有 token 的 Key 做点积，再用结果加权所有 Value。</p><p><strong>如果没有 KV Cache</strong>，每生成一个新 token，都要把前面所有 token 的 K 和 V 重新算一遍。生成 128 个 token，就要重算 128 次前缀。</p><p><strong>有了 KV Cache</strong>，前面 token 的 K 和 V 算过一次就存下来。生成新 token 时，只算当前 token 的 Q、K、V，把新的 K、V 追加到缓存里，然后拿当前 Q 去和缓存里所有 K 做注意力。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无 KV Cache：每步计算量 ∝ 序列长度²</span></span>
<span class="line"><span>有 KV Cache：每步计算量 ∝ 序列长度（只算当前 token 的 QKV + 注意力）</span></span></code></pre></div><p>KV Cache 是自回归推理能跑起来的基础设施。没有它，长序列生成会慢到不可用。</p><h3 id="_1-2-kv-cache-在哪个流程中用到" tabindex="-1">1.2 KV Cache 在哪个流程中用到 <a class="header-anchor" href="#_1-2-kv-cache-在哪个流程中用到" aria-label="Permalink to &quot;1.2 KV Cache 在哪个流程中用到&quot;">​</a></h3><p>KV Cache 贯穿推理的两个阶段：<strong>prefill 阶段写入，decode 阶段读取和追加</strong>。</p><p><strong>Prefill 阶段：写入 KV Cache</strong></p><p>请求到达后，模型先把整段 prompt 过一遍。这一步叫 prefill。</p><ul><li>输入：prompt 的所有 token</li><li>计算：每一层都对所有 token 算 K 和 V</li><li>输出：最后一个 token 位置的隐藏状态，用来采样第一个生成 token</li><li><strong>副作用：每一层的 K 和 V 被写入 KV Cache</strong></li></ul><p>Prefill 是并行的，所有 prompt token 一次算完。这一步的 KV 写入量 = prompt 长度 × 每 token KV 字节数 × 层数。</p><p><strong>Decode 阶段：读取 KV Cache，追加新 KV</strong></p><p>Prefill 完，开始逐 token 生成。每生成一个 token：</p><ol><li>当前 token 过模型，算出当前层的 Q、K、V</li><li><strong>当前 token 的 K、V 追加到 KV Cache</strong></li><li>当前 token 的 Q 去和 KV Cache 里<strong>所有</strong> K 做注意力</li><li>用注意力权重加权 KV Cache 里<strong>所有</strong> V</li><li>输出下一个 token 的隐藏状态，采样</li></ol><p><strong>每一步 decode 都要读一遍整个 KV Cache。</strong> 序列越长，读的 KV 越多，decode 越慢。这就是为什么长上下文解码会变慢。</p><h3 id="_1-3-kv-cache-和-pagedattention" tabindex="-1">1.3 KV Cache 和 PagedAttention <a class="header-anchor" href="#_1-3-kv-cache-和-pagedattention" aria-label="Permalink to &quot;1.3 KV Cache 和 PagedAttention&quot;">​</a></h3><p>vLLM 的核心创新是 <strong>PagedAttention</strong>：把 KV Cache 切成固定大小的 <strong>block</strong>，像操作系统管理内存页一样管理。</p><ul><li>每个 block 存固定数量 token 的 K 和 V（默认 <code>block_size = 16</code>）</li><li>block 在物理显存里不要求连续</li><li><code>block_table</code> 记录逻辑位置到物理 block 的映射</li><li>多个请求可以共享同一个物理 block（Prefix Caching 的基础）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>block 数量 = KV cache 字节数 / 每个 block 字节数</span></span>
<span class="line"><span>每个 block 字节数 = block_size × num_kv_heads × head_dim × 2(K和V) × dtype_bytes</span></span></code></pre></div><hr><h2 id="二、prefix-caching-是什么" tabindex="-1">二、Prefix Caching 是什么 <a class="header-anchor" href="#二、prefix-caching-是什么" aria-label="Permalink to &quot;二、Prefix Caching 是什么&quot;">​</a></h2><h3 id="_2-1-它不是一个独立的缓存" tabindex="-1">2.1 它不是一个独立的缓存 <a class="header-anchor" href="#_2-1-它不是一个独立的缓存" aria-label="Permalink to &quot;2.1 它不是一个独立的缓存&quot;">​</a></h3><p><strong>Prefix Caching 不是独立于 KV Cache 的另一个缓存，它是对已有 KV block 的复用策略。</strong></p><ul><li>KV Cache 是物理实体：显存里存 K 和 V 的 block。</li><li>Prefix Caching 是调度策略：当新请求的前缀和已有 block 的 hash 匹配时，直接复用那些 block，不重新计算。</li></ul><p>所以：</p><ul><li>没有 Prefix Caching，KV Cache 只存正在运行的请求的 KV，请求结束就释放。</li><li>有 Prefix Caching，请求结束后 KV block 不立即清空，留在池子里等后续请求命中。命中了就复用，没命中就被 LRU 淘汰。</li></ul><h3 id="_2-2-block-hash" tabindex="-1">2.2 Block Hash <a class="header-anchor" href="#_2-2-block-hash" aria-label="Permalink to &quot;2.2 Block Hash&quot;">​</a></h3><p>vLLM 对每个<strong>填满的</strong> KV block 计算一个 hash 值，hash 的输入是“该 block 前面的所有 token + 该 block 内的 token”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(prefix tokens + block tokens) &lt;--&gt; KV Block</span></span></code></pre></div><p>举例：<code>block_size = 16</code>。</p><ul><li>Block 1 的 hash 基于“block 1 内的 16 个 token”</li><li>Block 2 的 hash 基于“block 1 的全部 token + block 2 内的 16 个 token”</li><li>Block 3 的 hash 基于“block 1 + block 2 的全部 token + block 3 内的 16 个 token”</li></ul><p><strong>只有完全相同的 token 序列，才会产生相同的 hash。</strong> 任何位置的 token 不同，后续所有 block 的 hash 都会改变。</p><p><strong>Block 是匹配的最小单位。</strong> 即使两条请求在某个 block 中间才分叉（比如前 10 个 token 相同，第 11 个开始不同），这个 block 也不会被缓存，因为 vLLM 只缓存“填满的 block”。</p><h3 id="_2-3-一个请求进来时发生什么" tabindex="-1">2.3 一个请求进来时发生什么 <a class="header-anchor" href="#_2-3-一个请求进来时发生什么" aria-label="Permalink to &quot;2.3 一个请求进来时发生什么&quot;">​</a></h3><p><strong>第一步：查找可复用的 Block</strong></p><p>新请求到达时，调度器计算它第一个 block 的 hash，去全局 hash 表里查找。</p><ul><li><strong>命中</strong>：说明缓存中有完全相同的 token 序列的 block。vLLM 把这个物理 block 的引用计数加一，<strong>跳过这部分 token 的 prefill 计算</strong>。</li><li><strong>未命中</strong>：按普通流程处理，从第一个 token 开始 prefill。</li></ul><p>命中的 block 数量取决于<strong>从开头开始连续匹配的长度</strong>。如果第 1 个 block 命中、第 2 个命中、第 3 个不命中，那么只能复用前 2 个 block 的 KV，第 3 个开始需要重新计算。</p><p><strong>第二步：为未命中的部分分配新 Block</strong></p><p>对于未命中的部分，vLLM 按正常 prefill 流程，从空闲 block 队列中分配新的物理 block，计算 KV 并写入。</p><p><strong>这里有一个关键约束</strong>：如果开启了 chunked prefill，Prefix Caching 的查找<strong>只在第一个 chunk 执行</strong>。也就是说，如果一个请求的 prompt 被切成多个 chunk，只有第一个 chunk 的开头部分会去查 Prefix Caching，后续 chunk 不再查。</p><p><strong>第三步：解码阶段的 Block 增长</strong></p><p>请求进入 decode 后，每生成一个 token，如果当前 block 满了，就分配一个新 block。新 block 的 hash 基于“之前所有 token + 新 block 内的 token”计算，并加入全局 hash 表，<strong>未来可能有其他请求复用它</strong>。</p><h3 id="_2-4-引用计数" tabindex="-1">2.4 引用计数 <a class="header-anchor" href="#_2-4-引用计数" aria-label="Permalink to &quot;2.4 引用计数&quot;">​</a></h3><p>每个物理 KV block 有一个 <code>ref_cnt</code>，记录<strong>当前有多少个请求正在使用这个 block</strong>。</p><ul><li>一个请求独占一个 block 时，<code>ref_cnt = 1</code></li><li>另一个请求命中了相同前缀的 block 时，<code>ref_cnt</code> 变成 2</li><li>当一个请求结束，它释放自己引用的所有 block，对应的 <code>ref_cnt</code> 减一</li><li><strong>只有当 <code>ref_cnt</code> 降到 0 时，这个 block 才会被放回空闲队列</strong>，可能被后续请求复用，也可能被淘汰</li></ul><p>这就是 Prefix Caching 能“记住”已经结束的请求的前缀的原因：<strong>请求虽然结束了，但它的 block 因为 hash 还在表里，ref_cnt 归 0 后并没有被立即清空</strong>，而是留在池子里等待下一个命中。</p><h3 id="_2-5-淘汰策略" tabindex="-1">2.5 淘汰策略 <a class="header-anchor" href="#_2-5-淘汰策略" aria-label="Permalink to &quot;2.5 淘汰策略&quot;">​</a></h3><p>当空闲 block 耗尽、需要给新请求分配 block 时，vLLM 按以下优先级淘汰：</p><ol><li><strong>优先淘汰 <code>ref_cnt = 0</code> 的 block</strong>：即没有活跃请求在用的 block。正在被请求使用的 block（<code>ref_cnt &gt; 0</code>）不会被淘汰。</li><li><strong>在 <code>ref_cnt = 0</code> 的 block 中，优先淘汰 LRU</strong>（最近最少使用的）。</li><li><strong>如果多个 block 的最后访问时间相同，优先淘汰“位于最长前缀末尾”的 block</strong>——也就是说，越“叶子”的 block 越先被淘汰，保留更靠近根部的共享前缀。</li></ol><p>这套策略的效果是：<strong>被多个请求共享的长系统提示词的前缀 block，因为访问频繁，最不容易被淘汰；而只在少数请求末尾出现的 block，最先被回收。</strong></p><h3 id="_2-6-prefix-caching-不改变什么" tabindex="-1">2.6 Prefix Caching 不改变什么 <a class="header-anchor" href="#_2-6-prefix-caching-不改变什么" aria-label="Permalink to &quot;2.6 Prefix Caching 不改变什么&quot;">​</a></h3><ul><li><strong>不改变单路解码速度</strong>。它只减少 prefill 计算量，降低 TTFT，不改变 TPOT。</li><li><strong>不改变 KV 容量</strong>。它复用已有 block，不额外占显存。</li><li><strong>不改变输出结果</strong>。它只是跳过重复计算，KV 值本身不变。</li></ul><hr><h2 id="三、示例-前缀不重复时-prefix-caching-为什么帮不上忙" tabindex="-1">三、示例：前缀不重复时，Prefix Caching 为什么帮不上忙 <a class="header-anchor" href="#三、示例-前缀不重复时-prefix-caching-为什么帮不上忙" aria-label="Permalink to &quot;三、示例：前缀不重复时，Prefix Caching 为什么帮不上忙&quot;">​</a></h2><p>用一个具体例子把上面的机制串起来。示例参数如下，<strong>不是任何一次真实测试的结果，只是用来演示计算方式</strong>。</p><h3 id="_3-1-示例配置" tabindex="-1">3.1 示例配置 <a class="header-anchor" href="#_3-1-示例配置" aria-label="Permalink to &quot;3.1 示例配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td><code>block_size</code></td><td>16</td></tr><tr><td>prompt 长度</td><td>536 token</td></tr><tr><td>请求数</td><td>4 条</td></tr><tr><td>前缀</td><td>随机、不重复</td></tr></tbody></table><h3 id="_3-2-每条请求的-block-划分" tabindex="-1">3.2 每条请求的 Block 划分 <a class="header-anchor" href="#_3-2-每条请求的-block-划分" aria-label="Permalink to &quot;3.2 每条请求的 Block 划分&quot;">​</a></h3><p>536 token 需要：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ceil(536 / 16) = 34 个 block</span></span></code></pre></div><p>4 条请求，每条 34 个 block，共 136 个 block。</p><h3 id="_3-3-hash-匹配结果" tabindex="-1">3.3 Hash 匹配结果 <a class="header-anchor" href="#_3-3-hash-匹配结果" aria-label="Permalink to &quot;3.3 Hash 匹配结果&quot;">​</a></h3><p>每条请求的每个 block hash 都是唯一的，因为前缀不重复：</p><table tabindex="0"><thead><tr><th>请求</th><th>Block 1 hash</th><th>Block 2 hash</th><th>…</th><th>Block 34 hash</th></tr></thead><tbody><tr><td>请求 A</td><td>hash_A1</td><td>hash_A2</td><td>…</td><td>hash_A34</td></tr><tr><td>请求 B</td><td>hash_B1</td><td>hash_B2</td><td>…</td><td>hash_B34</td></tr><tr><td>请求 C</td><td>hash_C1</td><td>hash_C2</td><td>…</td><td>hash_C34</td></tr><tr><td>请求 D</td><td>hash_D1</td><td>hash_D2</td><td>…</td><td>hash_D34</td></tr></tbody></table><p><strong>没有任何一个 hash 是相同的。</strong> 请求 B 的第一个 block hash 和请求 A 的第一个 block hash 不同，后续更不可能相同。</p><h3 id="_3-4-调度流程" tabindex="-1">3.4 调度流程 <a class="header-anchor" href="#_3-4-调度流程" aria-label="Permalink to &quot;3.4 调度流程&quot;">​</a></h3><p><strong>请求 A 到达</strong>：</p><ul><li>查 hash 表，空，全部未命中。</li><li>分配 34 个新 block，执行 prefill 536 token。</li><li>34 个 block 写入 hash 表，<code>ref_cnt = 1</code>。</li><li>进入 decode。</li></ul><p><strong>请求 B 到达</strong>：</p><ul><li>查 hash 表，<code>hash_B1</code> 不在表里，未命中。</li><li>分配 34 个新 block，执行 prefill 536 token。</li><li>34 个 block 写入 hash 表，<code>ref_cnt = 1</code>。</li><li>进入 decode。</li></ul><p><strong>请求 C、D 同理。</strong></p><h3 id="_3-5-结果" tabindex="-1">3.5 结果 <a class="header-anchor" href="#_3-5-结果" aria-label="Permalink to &quot;3.5 结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>请求</th><th>命中 block 数</th><th>prefill token 数</th></tr></thead><tbody><tr><td>A</td><td>0</td><td>536</td></tr><tr><td>B</td><td>0</td><td>536</td></tr><tr><td>C</td><td>0</td><td>536</td></tr><tr><td>D</td><td>0</td><td>536</td></tr></tbody></table><p><strong>Prefix Caching 完全没有生效。</strong> 每条请求都要完整 prefill 自己的 536 token。</p><h3 id="_3-6-请求结束后" tabindex="-1">3.6 请求结束后 <a class="header-anchor" href="#_3-6-请求结束后" aria-label="Permalink to &quot;3.6 请求结束后&quot;">​</a></h3><p>请求 A 结束：</p><ul><li>它引用的 34 个 block，<code>ref_cnt</code> 从 1 降到 0。</li><li>这些 block 留在池子里，等待命中。</li><li><strong>但永远不会有第二个请求来命中它们</strong>，因为前缀不重复。</li><li>当空闲 block 不足时，这些 block 按 LRU 被淘汰。</li></ul><p><strong>这就是“前缀不重复，缓存帮不上忙”的原理</strong>：hash 全部唯一，没有复用，Prefix Caching 只是白白占着 block 等一个永远不会来的命中。</p><hr><h2 id="四、prefix-caching-与-kv-cache-的关系" tabindex="-1">四、Prefix Caching 与 KV Cache 的关系 <a class="header-anchor" href="#四、prefix-caching-与-kv-cache-的关系" aria-label="Permalink to &quot;四、Prefix Caching 与 KV Cache 的关系&quot;">​</a></h2><p>把两者放在一起：</p><table tabindex="0"><thead><tr><th>维度</th><th>KV Cache</th><th>Prefix Caching</th></tr></thead><tbody><tr><td>是什么</td><td>物理实体：存 K 和 V 的 block</td><td>调度策略：复用已有 block</td></tr><tr><td>何时写入</td><td>prefill 写 prompt 的 KV，decode 追加新 KV</td><td>不写入，只复用</td></tr><tr><td>何时读取</td><td>每步 decode 读全部 KV</td><td>请求到达时查 hash 表</td></tr><tr><td>何时释放</td><td>请求结束，ref_cnt 减一</td><td>ref_cnt 归 0 的 block 留在池子里</td></tr><tr><td>影响 TTFT</td><td>prefill 写入 KV 的时间</td><td>命中时跳过 prefill，降低 TTFT</td></tr><tr><td>影响 TPOT</td><td>每步读 KV 的时间</td><td>不改变 TPOT</td></tr><tr><td>占显存</td><td>是</td><td>复用已有 block，不额外占</td></tr></tbody></table><p><strong>一句话</strong>：KV Cache 是“存什么”，Prefix Caching 是“怎么复用”。两者是同一块显存上的两个视角。</p><hr><h2 id="五、一句话总结" tabindex="-1">五、一句话总结 <a class="header-anchor" href="#五、一句话总结" aria-label="Permalink to &quot;五、一句话总结&quot;">​</a></h2><p><strong>KV Cache 是自回归生成时缓存的 Key 和 Value 张量，prefill 阶段写入，decode 阶段每步读取并追加，避免重复计算前缀。vLLM 用 PagedAttention 把它切成固定大小的 block，用引用计数管理共享，用 LRU 淘汰冷数据。Prefix Caching 不是独立于 KV Cache 的另一个缓存，它就是对已有 KV block 的复用策略：新请求的 block hash 与全局 hash 表匹配时，直接复用物理 block、跳过 prefill。匹配是 token 级精确的，只有完全相同的 token 序列才能命中。前缀不重复时，所有 hash 唯一，Prefix Caching 不生效。</strong></p>`,92)])])}const b=a(c,[["render",h]]);export{k as __pageData,b as default};
